event_history = []


def log_event(event_name, event_data=None):
    """Append an event record to the module-level event_history list.

    event_data defaults to an empty dict rather than None so downstream
    consumers can always call .get() on it without a null check."""
    if not event_name:
        raise ValueError("event_name cannot be empty")

    event_record = {"name": event_name, "data": event_data or {}}
    event_history.append(event_record)
    return event_record
